// Some portions generated by Codex
package org.eclipse.rdf4j.sail.helpers;

import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.mockito.Mockito.CALLS_REAL_METHODS;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

import org.eclipse.rdf4j.sail.NotifyingSailConnection;
import org.eclipse.rdf4j.sail.SailConnection;
import org.junit.jupiter.api.Test;

class BindingTransportCapabilityTest {

	@Test
	void existingProvidersDefaultToNativeBindings() {
		SailConnection connection = mock(SailConnection.class, CALLS_REAL_METHODS);
		assertFalse(connection.supportsSPARQLBindingTransport());
	}

	@Test
	void nestedStandardAndNotifyingWrappersDelegateTheCapability() {
		NotifyingSailConnection connection = mock(NotifyingSailConnection.class);
		SailConnection wrapper = new SailConnectionWrapper(new NotifyingSailConnectionWrapper(connection));
		assertFalse(wrapper.supportsSPARQLBindingTransport());
		when(connection.supportsSPARQLBindingTransport()).thenReturn(true);
		assertTrue(wrapper.supportsSPARQLBindingTransport());
		when(connection.supportsSPARQLBindingTransport()).thenReturn(false);
		assertFalse(wrapper.supportsSPARQLBindingTransport());
	}
}
